const body = $input.first().json.body;
const headers = $input.first().json.headers;

const secret = headers['x-curiel-secret'];
if (!secret || secret !== $env.CURIEL_SECRET_TOKEN) {
  return [{ json: { valid: false, error: 'INVALID_SECRET' } }];
}

if (!body?.recipient?.email || !body?.notificationTitle) {
  return [{ json: { valid: false, error: 'MISSING_FIELDS' } }];
}

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailRegex.test(body.recipient.email)) {
  return [{ json: { valid: false, error: 'INVALID_EMAIL' } }];
}

return [{ json: { ...body, valid: true } }];

const data = $input.first().json;
if (data.valid === false) {
  throw new Error(`Validation failed: ${data.error}`);
}
return $input.all();

const data = $input.first().json;
const recipient = data.recipient;
const type = data.type || 'notification';
const title = data.notificationTitle;
const message = data.notificationMessage || '';
const inspectionId = data.inspectionId;
const frontendUrl = $env.FRONTEND_URL || 'https://curiel.vercel.app';

const typeConfig = {
  inspection_assigned: { icon: '&#128203;', color: '#17324a', label: 'Asignacion' },
  inspection_started: { icon: '&#9654;', color: '#3b82f6', label: 'Iniciada' },
  inspection_ready_for_review: { icon: '&#128269;', color: '#8b5cf6', label: 'Para Revision' },
  inspection_returned_for_correction: { icon: '&#9998;', color: '#f59e0b', label: 'Correccion' },
  inspection_finalized: { icon: '&#9989;', color: '#10b981', label: 'Finalizada' },
  inspection_cancelled: { icon: '&#10060;', color: '#ef4444', label: 'Cancelada' },
  inspection_rescheduled: { icon: '&#128259;', color: '#f97316', label: 'Reprogramada' },
  inspection_overdue: { icon: '&#9888;&#65039;', color: '#dc2626', label: 'Vencida' },
  inspection_reminder_30min: { icon: '&#9200;', color: '#2563eb', label: 'Recordatorio' },
  inspection_not_started: { icon: '&#9888;', color: '#d97706', label: 'No Iniciada' },
  alert_created: { icon: '&#128680;', color: '#dc2626', label: 'Alerta' },
  evaluation_received: { icon: '&#127942;', color: '#17324a', label: 'Evaluacion' }
};

const config = typeConfig[type] || { icon: '&#128172;', color: '#17324a', label: 'Notificacion' };

const inspectionLink = inspectionId
  ? `<div style='text-align:center;margin:24px 0'><a href='${frontendUrl}/inspections/${inspectionId}' style='display:inline-block;background:#17324a;color:#ffffff;padding:12px 28px;border-radius:10px;text-decoration:none;font-size:14px;font-weight:600'>Ver inspeccion</a></div>`
  : '';

const html = `
<div style='font-family:Arial,sans-serif;max-width:600px;margin:0 auto;padding:0'>
  <div style='background:${config.color}15;border-radius:16px 16px 0 0;padding:32px;text-align:center'>
    <span style='font-size:48px'>${config.icon}</span>
    <h1 style='color:${config.color};font-size:22px;margin:12px 0 4px;font-family:Georgia,serif'>${title}</h1>
    <p style='color:#6b7280;font-size:13px;margin:0'>${config.label}</p>
  </div>
  <div style='background:#ffffff;padding:32px;border:1px solid #e5e7eb;border-top:none;border-radius:0 0 16px 16px'>
    <p style='color:#374151;font-size:15px;line-height:1.7;margin:0 0 16px'>Hola <strong>${recipient.fullName || 'Usuario'}</strong>,</p>
    <p style='color:#374151;font-size:15px;line-height:1.7;margin:0 0 16px'>${message}</p>
    ${inspectionLink}
    <hr style='border:none;border-top:1px solid #e5e7eb;margin:24px 0'>
    <p style='color:#9ca3af;font-size:12px;text-align:center;margin:0'>CURIEL Inspecciones &middot; Sistema tecnico de gestion</p>
  </div>
</div>`;

return [{ json: { to: recipient.email, subject: `[CURIEL] ${title}`, html } }];
